def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    counts = {}
    for i in range(n):
        element = sites[i].get('element')
        counts[element] = counts.get(element, 0.0) + occ[i]
    population = sum(occ)
    if population <= 0.0:
        return 0.0
    expected = 1.0 - sum((value / population) ** 2 for value in counts.values())
    hetero = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            reduced = d / (radii[i] + radii[j])
            w = occ[i] * occ[j] * (1.0 - d / 6.0) ** 2 / (1.0 + reduced ** 6)
            weight += w
            if sites[i].get('element') != sites[j].get('element'):
                hetero += w
    if weight <= 0.0:
        return 0.0
    return hetero / weight - expected

