def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    contrast = [0.0 for x in sites]
    weights = [0.0 for x in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            if en[i] is not None and en[j] is not None:
                reduced = d / (radii[i] + radii[j])
                w = occ[j] * (1.0 - d / 6.0) ** 2 / (1.0 + reduced ** 6)
                contrast[i] += w * (en[j] - en[i])
                weights[i] += w
    total = 0.0
    weight = 0.0
    for i in range(n):
        if weights[i] > 0.0:
            total += occ[i] * (contrast[i] / weights[i]) ** 2
            weight += occ[i]
    return total / max(weight, 1e-12)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    nearest = [7.0 for x in sites]
    neighbors = s.get('neighbors') or []
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and occ[i] * occ[j] > 0.0 and 0.0 < d <= 6.0:
            nearest[i] = min(nearest[i], d)
    vectors = [[0.0, 0.0, 0.0] for x in sites]
    weights = [0.0 for x in sites]
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and occ[i] * occ[j] > 0.0 and 0.0 < d <= min(6.0, 1.25 * nearest[i]):
            fi = sites[i].get('frac_coords')
            fj = sites[j].get('frac_coords')
            image = b.get('image') or [0, 0, 0]
            if fi is not None and fj is not None:
                w = occ[j]
                for a in range(3):
                    vectors[i][a] += w * sum((fj[k] + image[k] - fi[k]) * matrix[k][a] for k in range(3)) / d
                weights[i] += w
    total = 0.0
    weight = 0.0
    for i in range(n):
        if weights[i] > 0.0:
            imbalance = sum(value ** 2 for value in vectors[i]) / weights[i] ** 2
            total += occ[i] * min(1.0, max(0.0, imbalance))
            weight += occ[i]
    return total / max(weight, 1e-12)
